/**
 * 跳转列表页并预置查询条件
 * @param {string} filePath 目标列表页组件路径
 * @param {Object} params 额外查询条件
 * @param {Object} [opts]
 * @param {boolean} [opts.excludeRegionParam] bug 5819：目标列表（如物业服务企业-非本地）
 *   不按首页区域树过滤时置 true，跳转不携带 parentDeptId，否则列表查出 0 条
 * @param {boolean} [opts.clearLocalOrgParam] bug 6576：目标列表（物业服务企业-总数）
 *   不得继承「是否本地机构」条件，为 true 时从缓存参数中删除该键
 */
navigateWithSearchParams(filePath, params, opts = {}) {
  const matchRoute = getCurrentRouterByFilePath(filePath)
  if (!matchRoute) {
    msgError('没有授权相关菜单，请联系管理员')
    return
  }
  const path = String(matchRoute.path || '').replace(':tableid', '')
  if (!path) {
    msgError('没有授权相关菜单，请联系管理员')
    return
  }
  const regionParams = opts.excludeRegionParam
    ? // 显式置空，覆盖缓存里可能残留的 parentDeptId（listMixins 会合并历史缓存参数）
    { parentDeptId: undefined }
    : this.portalQueryParams()
  const searchParams = { pageNum: 1, pageSize: 10, ...regionParams, ...params }
  // bug 6576：总数卡不带是否本地条件；delete 防止缓存残留 isLocalOrganization
  if (opts.clearLocalOrgParam) delete searchParams.isLocalOrganization
  this.$store.dispatch('common/saveSearchParams', {
    key: path,
    // 携带首页选择的区域条件（parentDeptId），使目标列表页按同一区域过滤
    params: searchParams
  })
  this.$router.push({ path })
},

