/**
 * bug #6576 回归：首页「物业服务企业数量」总数跳转不得带「是否本地机构」条件
 *
 * 现象：首页关键数据导航「物业服务企业数量」展示的是本地 + 非本地合计，
 *      但点总数跳列表后默认带上「是否本地机构 = 是」，条比总数少很多。
 * 期望：点总数 跳转不带 isLocalOrganization；点「本地」/「非本地」子项才带（1 / 0）。
 * 根因：src/views/home/v2/homeStatNav.js 的 KEY_DATA_STAT_NAV.company.params
 *      误带 isLocalOrganization: '1'（与 companyLocal 重复）。
 * 修复：company.params 只保留 bizState:'2'，并标 clearLocalOrgParam: true；
 *      index-v2.vue 跳转时 delete 缓存里的 isLocalOrganization（防历史缓存残留）。
 *
 * 运行：node e2e/home-v2/bug-6576-company-total-no-local-param.spec.mjs
 * 前置：npm run dev -- --port 8181 --strictPort
 */
import { chromium } from 'playwright'
import { mockGetInfo, mockDeptTreeInPermission, mockKeyData, mockTaskCount } from './home-v2-mocks.js'

const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8181'
const API_PREFIX = process.env.E2E_API_PREFIX || '/api/v2.0'
const VIEWPORT = { width: 1920, height: 1366 }
const COMPANY_LIST_PATH = '/index/company/companyManagement/property'

const mockRoutersWithCompanyList = [
  {
    name: 'Index',
    path: '/index',
    hidden: false,
    component: 'Layout',
    children: [
      { name: 'Home', path: 'index', component: 'home/index', meta: { title: '首页', icon: 'dashboard' } },
      {
        name: 'PropertyCompany',
        path: 'company/companyManagement/property',
        component: 'company/companyManagement/property/index',
        meta: { title: '物业服务企业', icon: 'list' }
      }
    ]
  }
]

function jsonResponse(body) {
  return { status: 200, contentType: 'application/json', body: JSON.stringify(body) }
}

async function main() {
  const browser = await chromium.launch({ headless: true })
  const context = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 1 })

  const companyPageRequests = []
  await context.route(`**${API_PREFIX}/**`, async (route) => {
    const url = route.request().url()
    const pathname = url.split(API_PREFIX)[1] || ''
    if (pathname.includes('/company/companyRecord/page')) {
      companyPageRequests.push({ url: pathname, query: url.split('?')[1] || '' })
    }
    if (pathname.includes('/system/platformConfig/getInfo')) {
      return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: { region: '320500', platformName: '苏住房智慧物业管理平台' } }))
    }
    if (pathname.includes('/getInfo')) return route.fulfill(jsonResponse(mockGetInfo))
    if (pathname.includes('/system/dept/treeInPermission')) return route.fulfill(jsonResponse(mockDeptTreeInPermission))
    if (pathname.includes('/menu/listRouters')) return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: mockRoutersWithCompanyList }))
    if (pathname.includes('/property/portal/getKeyData')) return route.fulfill(jsonResponse(mockKeyData))
    if (pathname.includes('/flowable/task/taskCount')) return route.fulfill(jsonResponse(mockTaskCount))
    if (pathname.includes('/secret/key')) return route.fulfill(jsonResponse({ code: 500, msg: 'skip sign in e2e' }))
    return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: [], rows: [], total: 0 }))
  })

  await context.addInitScript(() => {
    try {
      const origSessionGet = sessionStorage.getItem.bind(sessionStorage)
      Object.defineProperty(sessionStorage, 'getItem', {
        configurable: true,
        value: function (key) {
          if (key === 'Admin-Token') return 'e2e-mock-token'
          return origSessionGet(key)
        }
      })
      localStorage.setItem('layout-setting', JSON.stringify({ topNav: true, tagsView: true, fixedHeader: true, sidebarLogo: true }))
    } catch (e) {}
  })

  const page = await context.newPage()
  const errors = []
  page.on('pageerror', (e) => errors.push(String(e)))

  /** 读 store 缓存中的列表查询条件 */
  const savedParams = () =>
    page.evaluate((key) => {
      const store = window.__VUE_APP_STORE__
      if (!store) return null
      const params = store.state.common.cachedSearchParams.get(key)
      if (!params) return null
      return {
        hasLocalOrgKey: 'isLocalOrganization' in params,
        isLocalOrganization: params.isLocalOrganization,
        hasRegionKey: 'parentDeptId' in params,
        bizState: params.bizState
      }
    }, COMPANY_LIST_PATH)

  const gotoHome = async () => {
    await page.goto(`${BASE_URL}/#/index`, { waitUntil: 'domcontentloaded', timeout: 120000 })
    await page.waitForSelector('.home-v2', { timeout: 60000 })
  }

  const clickTotal = async () => {
    const total = page.locator('.kd__card--company .kd__main--clickable').first()
    await total.waitFor({ state: 'visible', timeout: 30000 })
    await total.click()
    await page.waitForSelector('.el-table', { timeout: 60000 })
    await page.waitForTimeout(1200)
  }

  const clickBreakdown = async (label) => {
    const row = page.locator('.kd__box--company', { hasText: label }).first()
    await row.waitFor({ state: 'visible', timeout: 30000 })
    await row.click()
    await page.waitForSelector('.el-table', { timeout: 60000 })
    await page.waitForTimeout(1200)
  }

  try {
    // ---------- 用例 1：点总数卡 → 不得带 isLocalOrganization ----------
    await gotoHome()
    companyPageRequests.length = 0
    await clickTotal()

    if (!companyPageRequests.length) {
      throw new Error(`未捕获物业服务企业列表请求：${JSON.stringify(companyPageRequests)}`)
    }
    const totalWithLocal = companyPageRequests.filter((r) => new URLSearchParams(r.query).has('isLocalOrganization'))
    if (totalWithLocal.length) {
      throw new Error(`「总数」跳转的列表请求仍携带 isLocalOrganization（bug #6576 未修复）：${totalWithLocal.map((r) => r.url).join(', ')}`)
    }
    const totalSaved = await savedParams()
    if (!totalSaved) throw new Error('总数跳转后未写入列表页缓存查询参数')
    if (totalSaved.hasLocalOrgKey) {
      throw new Error(`「总数」跳转后缓存仍存在 isLocalOrganization 键（bug #6576）：${JSON.stringify(totalSaved)}`)
    }
    if (totalSaved.bizState !== '2') {
      throw new Error(`「总数」跳转应保留 bizState='2'（已备案口径），实际：${JSON.stringify(totalSaved)}`)
    }

    // ---------- 用例 2：「本地」→ isLocalOrganization='1' ----------
    await gotoHome()
    companyPageRequests.length = 0
    await clickBreakdown('本地')
    const localSaved = await savedParams()
    if (!localSaved || localSaved.isLocalOrganization !== '1') {
      throw new Error(`「本地」跳转应带 isLocalOrganization='1'，实际：${JSON.stringify(localSaved)}`)
    }
    if (!companyPageRequests.some((r) => new URLSearchParams(r.query).get('isLocalOrganization') === '1')) {
      throw new Error(`「本地」跳转的列表请求未携带 isLocalOrganization=1：${JSON.stringify(companyPageRequests)}`)
    }

    // ---------- 用例 3：「非本地」→ '0' 且不带 parentDeptId（叠加 bug#5819） ----------
    await gotoHome()
    companyPageRequests.length = 0
    await clickBreakdown('非本地')
    const nonLocalSaved = await savedParams()
    if (!nonLocalSaved || nonLocalSaved.isLocalOrganization !== '0') {
      throw new Error(`「非本地」跳转应带 isLocalOrganization='0'，实际：${JSON.stringify(nonLocalSaved)}`)
    }
    const nonLocalWithRegion = companyPageRequests.filter((r) => new URLSearchParams(r.query).has('parentDeptId'))
    if (nonLocalWithRegion.length) {
      throw new Error(`「非本地」跳转的列表请求仍携带 parentDeptId（bug #5819 回退）：${nonLocalWithRegion.map((r) => r.url).join(', ')}`)
    }

    // ---------- 用例 4：先「本地」再回首页点总数 → 必须清掉缓存残留 ----------
    await gotoHome()
    companyPageRequests.length = 0
    await clickTotal()
    const afterLocalSaved = await savedParams()
    if (!afterLocalSaved) throw new Error('总数跳转后未写入列表页缓存查询参数')
    if (afterLocalSaved.hasLocalOrgKey) {
      throw new Error(`从「本地」进入后再点总数，缓存 isLocalOrganization 残留未被清除（bug #6576）：${JSON.stringify(afterLocalSaved)}`)
    }
    const afterLocalReq = companyPageRequests.filter((r) => new URLSearchParams(r.query).has('isLocalOrganization'))
    if (afterLocalReq.length) {
      throw new Error(`从「本地」进入后再点总数，列表请求仍携带 isLocalOrganization：${afterLocalReq.map((r) => r.url).join(', ')}`)
    }

    if (errors.length) throw new Error(`页面运行时报错：${errors.join(' | ')}`)

    console.log('bug #6576 回归通过：总数跳转不带 isLocalOrganization（含缓存残留场景）；本地=1 / 非本地=0 且非本地不带 parentDeptId')
  } finally {
    await browser.close()
  }
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

